@meta.ShaderSource('scan.wgsl')
const String source = r'''

// import "shared/uniforms.wgsl"
struct World {
world_to_screen: mat4x4f,
viewport: vec2f,
tolerance: f32,
};

struct StorageOffsets {
geometry_frame: u32,
geometry_frame_inverse: u32,
geometry_vertex: u32,
geometry_covertex: u32,
geometry_edge: u32,

topology_vertex: u32,
topology_edge: u32,
topology_face: u32,
topology_covertex: u32,
topology_face_boundary: u32,
topology_draw: u32,
topology_draw_count: u32,

style_vertex: u32,
style_edge: u32,
style_face: u32,

render_geometry_capacity: u32
};
// end import "shared/uniforms.wgsl"

// import "shared/structs.wgsl"
struct Cubic2 {
p0: vec2f,
p1: vec2f,
p2: vec2f,
p3: vec2f,
}

struct VertexStyle {
decoration_start: u32,
decoration_count: u32,
}

struct EdgeStyle {
decoration_start: u32,
decoration_count: u32,
width: f32,
}

struct FaceStyle {
decoration_start: u32,
decoration_count: u32,
}

struct VertexTopology {
disk_start: u32,
parent: u32,
}

struct EdgeTopology {
vertex_start: u32,
vertex_end: u32,
parent: u32,
}

struct FaceTopology {
boundary_start: u32,
boundary_count: u32,
parent: u32,
}

struct CovertexTopology {
edge: u32,
is_start: u32,
next: u32,
}

struct FaceBoundaryEntry {
edge: u32,
is_forward: u32,
}

struct DrawEntry {
cell: u32,
kind: u32,
decoration_offset: u32,
}

struct DrawIndirectArgs {
vertex_count: u32,
instance_count: u32,
first_vertex: u32,
first_instance: u32,
}

struct DecorationEntry {
kind: u32,
v0: f32,
v1: f32,
v2: f32,
v3: f32,
}

const DECORATION_NONE = DecorationEntry(
DECORATION_KIND_NONE,
0.0, 0.0, 0.0, 0.0
);

const DECORATION_KIND_NONE = 0;
const DECORATION_KIND_COLOR = 1;
const DECORATION_KIND_FRAGMENT_SHADER = 2;
// end import "shared/structs.wgsl"


@group(0) @binding(1) var<uniform> storage_offsets: StorageOffsets;

@group(2) @binding(0) var<storage, read_write> count: array<u32>;
@group(2) @binding(1) var<storage, read_write> indirect_args: array<DrawIndirectArgs>;

const SCAN_THREADS = 256u;
var<workgroup> partials: array<u32, SCAN_THREADS>;

@compute @workgroup_size(256)
fn main(@builtin(local_invocation_id) local_id: vec3u) {
let n = storage_offsets.topology_draw_count;
let tid = local_id.x;

let chunk = (n + SCAN_THREADS - 1u) / SCAN_THREADS;
let start = min(tid * chunk, n);
let end = min(start + chunk, n);

var sum = 0u;
for (var i = start; i < end; i++) {
sum += count[i];
}
partials[tid] = sum;
workgroupBarrier();

for (var stride = 1u; stride < SCAN_THREADS; stride *= 2u) {
var v = 0u;
if (tid >= stride) {
v = partials[tid - stride];
}
workgroupBarrier();
partials[tid] += v;
workgroupBarrier();
}

let total = partials[SCAN_THREADS - 1u];
var offset = partials[tid] - sum;

for (var i = start; i < end; i++) {
let c = count[i];
count[i] = offset;
offset += c;
}

if (tid == SCAN_THREADS - 1u) {
count[n] = total;
}

storageBarrier();

let capacity = storage_offsets.render_geometry_capacity;
for (var c = tid; c < n; c += SCAN_THREADS) {
let start = min(count[c], capacity);
let end = min(count[c + 1], capacity);
indirect_args[c] = DrawIndirectArgs((end - start) * 6u, 1u, start * 6u, 0u);
}
}
''';

